#include <functional>
#include <utility>
#include <vector>

template <class T, class Less = std::less<T>>
long long insertionSort(std::vector<T>& a, Less less = Less{})
{
    long long shifts = 0;
    for (std::size_t i = 1; i < a.size(); ++i)
    {
        T value = std::move(a[i]);
        std::size_t j = i;
        while (j > 0 && less(value, a[j - 1]))
        {
            a[j] = std::move(a[j - 1]);
            --j;
            ++shifts;
        }
        a[j] = std::move(value);
    }
    return shifts;
}

template <class T, class Less = std::less<T>>
void selectionSort(std::vector<T>& a, Less less = Less{})
{
    for (std::size_t i = 0; i + 1 < a.size(); ++i)
    {
        std::size_t smallest = i;
        for (std::size_t j = i + 1; j < a.size(); ++j)
            if (less(a[j], a[smallest])) smallest = j;
        if (smallest != i) std::swap(a[i], a[smallest]);
    }
}

template <class T, class Less = std::less<T>>
bool isSorted(const std::vector<T>& a, Less less = Less{})
{
    for (std::size_t i = 1; i < a.size(); ++i)
        if (less(a[i], a[i - 1])) return false;
    return true;
}

long long countInversionsSlow(const std::vector<int>& a)
{
    long long count = 0;
    for (std::size_t i = 0; i < a.size(); ++i)
        for (std::size_t j = i + 1; j < a.size(); ++j)
            if (a[i] > a[j]) ++count;
    return count;
}

