#include <string>

struct Card { int rank; char suit; };
static bool byRank(const Card& a, const Card& b) { return a.rank < b.rank; }

TEST("insertion sort") {
    std::vector<int> a{ 5, 2, 4, 6, 1, 3 };
    CHECK_EQ(insertionSort(a), 9LL);
    CHECK_EQ(a, (std::vector<int>{ 1, 2, 3, 4, 5, 6 }));
    std::vector<int> sorted{ 1, 2, 3 };
    CHECK_EQ(insertionSort(sorted), 0LL);
    std::vector<int> empty;
    CHECK_EQ(insertionSort(empty), 0LL);
}
TEST("shifts equal inversions") {
    std::vector<int> a{ 8, 3, 9, 1, 1, 7, 2, 6, 6, 0 };
    long long inversions = countInversionsSlow(a);
    CHECK_EQ(inversions, 28LL);
    CHECK_EQ(insertionSort(a), inversions);
    std::vector<int> reversed;
    for (int i = 100; i > 0; --i) reversed.push_back(i);
    CHECK_EQ(countInversionsSlow(reversed), 4950LL);
    CHECK_EQ(insertionSort(reversed), 4950LL);
}
TEST("insertion sort is stable") {
    std::vector<Card> hand{ { 5, 'h' }, { 2, 's' }, { 5, 'c' }, { 2, 'd' }, { 9, 'h' }, { 5, 's' } };
    insertionSort(hand, byRank);
    std::string order;
    for (const auto& c : hand) order += std::to_string(c.rank) + c.suit + " ";
    CHECK_EQ(order, std::string("2s 2d 5h 5c 5s 9h "));
}
TEST("selection sort and comparators") {
    std::vector<std::string> words{ "pear", "fig", "banana", "kiwi" };
    selectionSort(words);
    CHECK_EQ(words, (std::vector<std::string>{ "banana", "fig", "kiwi", "pear" }));
    selectionSort(words, [](const std::string& a, const std::string& b) { return a.size() < b.size(); });
    CHECK(isSorted(words, [](const std::string& a, const std::string& b) { return a.size() < b.size(); }));
    std::vector<int> d{ 3, 9, 1, 9 };
    selectionSort(d, std::greater<int>{});
    CHECK_EQ(d, (std::vector<int>{ 9, 9, 3, 1 }));
}
TEST("is it sorted?") {
    CHECK(isSorted(std::vector<int>{}));
    CHECK(isSorted(std::vector<int>{ 4 }));
    CHECK(isSorted(std::vector<int>{ 1, 1, 2 }));
    CHECK(!isSorted(std::vector<int>{ 1, 3, 2 }));
    CHECK(isSorted(std::vector<int>{ 3, 2, 2 }, std::greater<int>{}));
}

